def test_null_propagation(self):
    result = self.query(
        "SELECT NULL + 1, NULL - 1, NULL * 2, NULL / 2, -NULL, "
        "NULL || 'x', NULL = 1, NULL LIKE '%', "
        "NULL BETWEEN 1 AND 2, NULL IN (1) FROM one"
    )
    self.assertEqual(result.rows, [(None,) * 10])

def test_null_wins_over_incompatible_operand_types(self):
    result = self.query(
        "SELECT NULL + 'a', 'a' + NULL, NULL * TRUE, "
        "TRUE * NULL FROM one"
    )
    self.assertEqual(result.rows, [(None, None, None, None)])

